-- Translations admin page — the route /system/settings/translations was
-- censused ({kind:"page"}) but its sidebar link and ALL of its i18n keys were
-- never seeded: the page rendered raw keys and was unreachable from nav.
-- Seeds the nav label (system.settings.tabs.translations) + the page's own
-- keys (system.settings.translations.*) — 7 UI languages.
ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
